// --- Helpers -----------------------------------------------------------

function toDateOnly(d) {
    return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

export function getFeaturedFestival(referenceDate = new Date()) {
    const today = toDateOnly(referenceDate);
    const sorted = [...FESTIVALS_2026].sort((a, b) => new Date(a.date) - new Date(b.date));

    // Today's festival, if any, takes priority.
    const todays = sorted.find((f) => toDateOnly(new Date(f.date)).getTime() === today.getTime());
    if (todays) return todays;

    // Otherwise the next upcoming one.
    const next = sorted.find((f) => new Date(f.date) >= today);
    return next || sorted[sorted.length - 1];
}

export function getUpcomingFestivals(referenceDate = new Date()) {
    const today = toDateOnly(referenceDate);
    return [...FESTIVALS_2026]
        .filter((f) => toDateOnly(new Date(f.date)) >= today)
        .sort((a, b) => new Date(a.date) - new Date(b.date));
}

export function getPastFestivals(referenceDate = new Date()) {
    const today = toDateOnly(referenceDate);
    return [...FESTIVALS_2026]
        .filter((f) => toDateOnly(new Date(f.date)) < today)
        .sort((a, b) => new Date(b.date) - new Date(a.date));
}